import Foundation

/// The voice a learner's public profile speaks with in Find people
/// (2026-10-12, founder: "I'm Korean, so a Korean voice — Asian for Asian,
/// the country's own voice first"). Keyed by the NATIVE language, which is
/// the closest thing the app knows to where someone is from (`UserPersona.country`
/// is where they live). Cartesia library voices: each speaks the target
/// language with its own accent, and the servers allow them (`isStockVoice`).
/// A native language with no voice of its own uses its region's.
/// Built by scripts/people-voice-casting.py; two of each where Cartesia has them.
struct ProfileVoice: Identifiable, Hashable {
    enum Gender: String { case female, male }
    let id: String
    let name: String
    let gender: Gender

    static func options(forNative native: String) -> [ProfileVoice] {
        table[native] ?? table["en"] ?? []
    }

